import config from "./pictures.json";
// Generated by `npm run tiles`: tile id -> index in the grid, row by row.
import tileMap from "./tile-map.json";

// About a pigeon card: shown in a dialog when its picture is finished, and in the collection
// on the home page. Every card is free to use and always credited.
export type CardInfo = {
  // The kind of pigeon, or the breed.
  kind: string;
  // Who made the drawing, and in which book or collection.
  credit: string;
  license: string;
  // The picture's page on Wikimedia Commons.
  url: string;
};

type PictureConfig = {
  name: string;
  cols: number;
  rows: number;
  // Pictures without a card are old ones that are no longer handed out.
  card?: CardInfo;
};

export type Picture = {
  id: string;
  name: string;
  cols: number;
  rows: number;
  tileCount: number;
  // Tile ids in grid order: tileIds[index] is the tile at that position.
  tileIds: string[];
  card?: CardInfo;
};

export const PICTURES: Picture[] = Object.entries(
  config as Record<string, PictureConfig>,
).map(([id, p]) => {
  const tiles = (tileMap as Record<string, Record<string, number>>)[id] ?? {};
  const tileIds: string[] = [];
  for (const [tileId, index] of Object.entries(tiles)) tileIds[index] = tileId;
  return {
    id,
    name: p.name,
    cols: p.cols,
    rows: p.rows,
    tileCount: p.cols * p.rows,
    tileIds,
    card: p.card,
  };
});

// The pigeon cards: the pictures that new topics and new levels get.
export const CARDS = PICTURES.filter((p) => p.card);

// The first picture is the old one every topic used to have; saves keep using it.
export const DEFAULT_PICTURE_ID = PICTURES[0].id;

export const pictureById = (id: string) =>
  PICTURES.find((p) => p.id === id) ?? PICTURES[0];

export const isPictureId = (id: unknown): id is string =>
  PICTURES.some((p) => p.id === id);

export const isTileOf = (picture: Picture, tileId: unknown): tileId is string =>
  typeof tileId === "string" && picture.tileIds.includes(tileId);

export const tileUrl = (pictureId: string, tileId: string) =>
  `/tiles/${pictureId}/${tileId}.webp`;

// Tall pictures are cut into more rows than columns, so they're shown narrower.
export const isPortrait = (picture: Picture) => picture.rows > picture.cols;

const LICENSE_URLS: Record<string, string> = {
  "Public domain": "https://creativecommons.org/publicdomain/mark/1.0/",
  CC0: "https://creativecommons.org/publicdomain/zero/1.0/",
};

export const licenseUrl = (license: string) => LICENSE_URLS[license] ?? "";

// A random card for a topic. It prefers one that no existing topic has (`taken`) and the
// topic itself hasn't finished (`avoid`), so pictures only repeat once there are more
// topics and levels than cards.
export function pickPictureId(
  taken: Iterable<string>,
  avoid: Iterable<string> = [],
) {
  const takenIds = new Set(taken);
  const avoidIds = new Set(avoid);
  const pool =
    [
      CARDS.filter((p) => !takenIds.has(p.id) && !avoidIds.has(p.id)),
      CARDS.filter((p) => !avoidIds.has(p.id)),
      CARDS,
    ].find((cards) => cards.length) ?? PICTURES;
  return pool[Math.floor(Math.random() * pool.length)].id;
}

// The old photo isn't handed out any more. Topics that still have it get a pigeon card
// instead: a random one that no other topic has. Every revealed square moves to the same
// place in the new picture (both have 40 squares), so no progress is lost.
export function swapOldPictures(
  topics: {
    pictureId: string;
    revealed: string[];
    completedPictures: string[];
  }[],
) {
  for (const topic of topics) {
    const old = pictureById(topic.pictureId);
    if (old.card) continue;
    const next = pictureById(
      pickPictureId(
        topics.map((t) => t.pictureId),
        topic.completedPictures,
      ),
    );
    if (next.id === old.id) continue;
    topic.revealed = topic.revealed
      .map((tileId) => old.tileIds.indexOf(tileId))
      .filter((index) => index >= 0 && index < next.tileCount)
      .map((index) => next.tileIds[index]);
    topic.pictureId = next.id;
    // A finished picture that was waiting for "Start next level" counts as found.
    if (
      topic.revealed.length >= next.tileCount &&
      !topic.completedPictures.includes(next.id)
    ) {
      topic.completedPictures.push(next.id);
    }
  }
}

// Saves from before tile ids stored revealed squares as grid indexes.
export function tileIdsFromLegacy(picture: Picture, revealed: unknown[]) {
  const ids = revealed.map((value) =>
    typeof value === "number" ? picture.tileIds[value] : value,
  );
  return [...new Set(ids)].filter((id) => isTileOf(picture, id));
}
